#include <iostream>
#include <map>
#include <string>

int main()
{
    // 1. std::multimap demonstration (duplicate keys allowed)
    std::multimap<int, double> multi;
    multi.insert({15, 2.7});
    multi.insert({15, 99.3});
    multi.insert({10, 22.22});

    std::cout << "multimap count(15): " << multi.count(15) << '\n';
    for (const auto& [key, val] : multi)
    {
        std::cout << key << " -> " << val << '\n';
    }

    // 2. std::map demonstration (unique keys, operator[])
    std::map<int, double> uniqueMap;
    uniqueMap.insert({15, 2.7});
    uniqueMap.insert({15, 99.3}); // Duplicate key ignored

    uniqueMap[25] = 33.33; // Inserts new key 25
    uniqueMap[25] = 9999.99; // Modifies existing key 25

    std::cout << "\nmap contents:\n";
    for (const auto& [key, val] : uniqueMap)
    {
        std::cout << key << " -> " << val << '\n';
    }

    return 0;
}

#include <iostream>
#include <stack>
#include <vector>
#include <list>

template <typename StackType>
void processStack(StackType& s, const std::string& name)
{
    std::cout << name << " push: ";
    for (int i = 1; i <= 4; ++i)
    {
        s.push(i * 10);
        std::cout << s.top() << ' ';
    }
    std::cout << "\n" << name << " pop: ";
    while (!s.empty())
    {
        std::cout << s.top() << ' ';
        s.pop();
    }
    std::cout << "\n\n";
}

int main()
{
    // Default deque-backed stack
    std::stack<int> dequeStack;
    processStack(dequeStack, "dequeStack");

    // Vector-backed stack
    std::stack<int, std::vector<int>> vectorStack;
    processStack(vectorStack, "vectorStack");

    // List-backed stack
    std::stack<int, std::list<int>> listStack;
    processStack(listStack, "listStack");

    return 0;
}
